SELECT

FROM bt_ai_skill a
WHERE a.status_cd = '00A'
  AND a.space_id = #{spaceId}
  AND a.bot_id = #{botId}
  AND a.skill_id = #{skillId}
  AND a.creator_id = #{userId}

SELECT a.id, a.space_id, a.bot_id, a.skill_id, b.bot_name, b.bot_use
FROM bt_ai_skill a
LEFT JOIN bt_bot b ON a.bot_id = b.bot_id AND b.status_cd = '00A'
WHERE a.status_cd = '00A'
  AND a.space_id = #{spaceId}
  AND a.skill_id = #{skillId}

SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_ai_skill
WHERE status_cd = '00A'
  AND bot_id IS NOT NULL
  AND space_id = #{spaceId}
  AND skill_id = #{skillId}
  AND creator_id = #{userId}
